implementation_steps.code_block:
request = { id, svgPath, size }
connect_or_start_broker()
send(request)
response = wait_with_timeout(id)
if response.ok: load_bitmap(response.path)
finally: cleanup_request_files(id)

environment ??= await CreateEnvironmentAsync()
await renderGate.WaitAsync()
try { reset_surface(); navigate(svg); return capture(size); }
finally { clear_request_state(); renderGate.Release(); }
